mapper.select:
/*selectMasterMdCmCmsItemChangeReqList*/ SELECT H.REQ_NO /* 요청번호 */ ,H.CMS_CATLG_ID /* 상품정보코드 */ /* ↓ 요청 시점 스냅샷. CMSCATLG 현재값이 아니다 - 요청 당시 화면이 그대로 남는다 */ ,DECODE(H.STATUS, 'D', '미사용', '사용') AS STATUS_NM /* 상품상태 */ ,H.DESCRIPTION_LOC /* 품목명 */ ,H.MODEL_INFO /* 모델번호 */ ,H.SPECIFICATION /* 규격 */ ,(SELECT MK.TEXT1 FROM ICOMCOD1 MK WHERE MK.TYPE = 'M104' AND MK.CODE = H.MAKER_CODE) AS MAKER_NAME /* 제조사명 */ ,H.MAKER_CODE /* 제조사코드 */ ,(SELECT OG.TEXT2 FROM ICOMCOD1 OG WHERE OG.TYPE = 'M001' AND OG.CODE = H.ORIGIN_CODE) AS ORIGIN_NAME /* 원산지명 */ ,H.ORDER_MEASURE /* 단위 */ ,D.REQ_SEQ /* 변경항목 순번 */ ,D.JOB_COLUMN /* 변경항목(원컬럼명) */
/* 변경사유 : 상품상태는 사유코드(M182), 그 외는 텍스트 (상태변경 팝업 규약과 동일) */ ,NVL((SELECT RS.TEXT1 FROM ICOMCOD1 RS WHERE RS.TYPE = 'M182' AND RS.CODE = D.CHANGE_REASON_CODE) , D.CHANGE_REASON_REMARK) AS CHANGE_REASON /* 변경사유 */ /* 대체코드 : 사유가 '중복존재'(DUP)일 때만 값이 있다 */ ,CASE WHEN D.CHANGE_REASON_CODE = 'DUP' THEN D.ALT_CATLG_ID ELSE '' END AS ALT_CODE /* 대체코드 */ ,(SELECT U1.USER_NAME_LOC FROM ICOMLUSR U1 WHERE U1.USER_ID = H.REQ_USER_ID) AS REQ_USER_NAME /* 요청자 */ ,H.REQ_USER_ID /* 요청자 ID */ ,SUBSTR(H.REQ_DATE,1,4) || '/' || SUBSTR(H.REQ_DATE,5,2) || '/' || SUBSTR(H.REQ_DATE,7,2) || ' ' || SUBSTR(H.REQ_TIME,1,2) || ':' || SUBSTR(H.REQ_TIME,3,2) AS REQ_DATETIME /* 요청일시 */ /* 이 요청번호의 변경항목 수 - 목업의 '복수항목 요청건수 3건' */ ,(SELECT COUNT(*) FROM CMSCATLG_REQ_DT C WHERE C.REQ_NO = H.REQ_NO) AS ITEM_CNT /* 변경항목수 */ FROM CMSCATLG_REQ H, CMSCATLG_REQ_DT D WHERE H.REQ_NO = D.REQ_NO AND H.REQ_STATUS = 'REQ'
AND H.REQ_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND H.REQ_NO IN
#{item}
AND H.REQ_NO = #{st_req_no}
AND H.CMS_CATLG_ID IN
UPPER(#{item})
AND H.CMS_CATLG_ID = UPPER(#{st_cmscatlg})
AND EXISTS (SELECT 1 FROM CMSCATLG_REQ_DT C2 WHERE C2.REQ_NO = H.REQ_NO AND C2.JOB_COLUMN = #{st_job_column})
AND (SELECT COUNT(*) FROM CMSCATLG_REQ_DT C WHERE C.REQ_NO = H.REQ_NO) = 1
AND (SELECT COUNT(*) FROM CMSCATLG_REQ_DT C WHERE C.REQ_NO = H.REQ_NO) > 1
AND H.DESCRIPTION_LOC LIKE '%' || #{st_item_name} || '%'
AND H.MODEL_INFO LIKE '%' || #{st_model_info} || '%'
AND H.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND H.MAKER_CODE = #{st_maker_code}
AND EXISTS (SELECT 1 FROM ICOMLUSR U WHERE U.USER_ID = H.REQ_USER_ID AND U.USER_NAME_LOC LIKE '%' || #{st_req_user_name} || '%')
ORDER BY H.REQ_NO DESC, D.REQ_SEQ

mapper.update:

/*updateMasterMdCmCmsItemChangeReqApprove*/
UPDATE CMSCATLG_REQ
   SET REQ_STATUS     = 'APR'
     , PROC_USER_ID   = #{st_user_id}
     , PROC_DATE      = TO_CHAR(SYSDATE,'YYYYMMDD')
     , PROC_TIME      = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE REQ_NO     = #{st_req_no}
   AND REQ_STATUS = 'REQ'


/*updateMasterMdCmCmsItemChangeReqReject*/
UPDATE CMSCATLG_REQ
   SET REQ_STATUS     = 'REJ'
     , REJECT_REASON  = #{st_reject_reason}
     , PROC_USER_ID   = #{st_user_id}
     , PROC_DATE      = TO_CHAR(SYSDATE,'YYYYMMDD')
     , PROC_TIME      = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE REQ_NO     = #{st_req_no}
   AND REQ_STATUS = 'REQ'


/*updateMasterMdCmCmsItemChangeReqApplyCatlg*/
UPDATE CMSCATLG
   SET ${st_job_column} = F_HST_CMSCATLG( CMS_CATLG_ID
                                        , #{st_job_column}
                                        , #{st_new_data}
                                        , #{st_user_id}
                                        , #{st_reason_code}
                                        , #{st_reason_remark}
                                        , #{st_alt_code} )




     , MAKER_NAME = (SELECT MD.TEXT1 FROM ICOMCOD1 MD
                      WHERE MD.TYPE = 'M104' AND MD.CODE = #{st_new_data})



     , CHANGE_USER_ID = #{st_user_id}
     , CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE CMS_CATLG_ID = #{st_catlg_id}


/*updateMasterMdCmCmsItemChangeReqApplyReason*/
UPDATE CMSCATLG
   SET CHANGE_REASON_CODE   = #{st_reason_code}
     , CHANGE_REASON_REMARK = #{st_reason_remark}
     , ALT_CATLG_ID         = #{st_alt_code}
 WHERE CMS_CATLG_ID = #{st_catlg_id}


/*updateMasterMdCmCmsItemChangeReqApplyBuyInfoUnuse*/
UPDATE CMSPRICE
   SET STATUS = F_HST_CMSPRICE( CMS_CATLG_ID
                              , CATLG_SEQ
                              , 'STATUS'
                              , #{st_new_status}
                              , #{st_user_id}
                              , #{st_reason_code}
                              , #{st_reason_remark} )
     , SUPPLY_REASON_CODE   = #{st_reason_code}
     , SUPPLY_REASON_REMARK = #{st_reason_remark}
     , CHANGE_USER_ID       = #{st_user_id}
     , CHANGE_DATE          = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME          = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE CMS_CATLG_ID = #{st_catlg_id}
   AND NVL(STATUS, ' ') != #{st_new_status}
